-- File: 02-ack.sql
-- Purpose: admin 確認收到一份 critical 食安檢舉（acknowledge），停止 4 小時 SLA 計時
-- When to use: admin UI 故障時，admin 直接連 DB 標記已收到檢舉（避免 SLA 持續計時觸發告警）
-- Variables to fill:
--   :report_id — food_safety_reports.id (bigint TSID)
--   :admin_id  — 執行 ack 的 admin 帳號 id (bigint TSID)
-- Audit: 執行後將完整 SQL + 結果貼到 Discord #food-safety-actions channel 留紀錄
-- Generated by B-169 (issue #722) — 2026-05-07

BEGIN;

-- 1. ack 該食安檢舉
--    僅當 acknowledged_at IS NULL 才更新（避免覆蓋既有 ack）
UPDATE food_safety_reports
SET
    acknowledged_at = now(),
    acknowledged_by_admin_id = :admin_id,
    updated_at = now()
WHERE id = :report_id
  AND acknowledged_at IS NULL
RETURNING id, status, acknowledged_at, acknowledged_by_admin_id, created_at;

-- 2. 驗證：確認 ack 結果（admin 應在 COMMIT 前確認此筆是預期的檢舉）
SELECT
    id,
    target_seller_id,
    target_product_id,
    reporter_phone,
    reporter_name,
    LEFT(description, 100) AS description_preview,
    status,
    acknowledged_at,
    acknowledged_by_admin_id,
    created_at,
    EXTRACT(EPOCH FROM (acknowledged_at - created_at)) / 60 AS ack_latency_minutes
FROM food_safety_reports
WHERE id = :report_id
;

-- 確認以上輸出無誤後改為 COMMIT；若誤點則 ROLLBACK
ROLLBACK; -- 確認後改 COMMIT;
